const jalaliParts = (iso) => {
 const [y,m,d]=String(iso).split('-').map(Number);
 const date=new Date(y,m-1,d,12);
 const parts=new Intl.DateTimeFormat('en-u-ca-persian',{year:'numeric',month:'numeric',day:'numeric'}).formatToParts(date);
 return {year:Number(parts.find(p=>p.type==='year')?.value),month:Number(parts.find(p=>p.type==='month')?.value),day:Number(parts.find(p=>p.type==='day')?.value)};
};
const isoLocal = date => `${date.getFullYear()}-${String(date.getMonth()+1).padStart(2,'0')}-${String(date.getDate()).padStart(2,'0')}`;
const jalaliMonthDays = (year,month) => {
 const found=[];
 const start=new Date(year+621,2,15,12);
 const end=new Date(year+622,3,5,12);
 for(let d=new Date(start);d<=end;d.setDate(d.getDate()+1)){
  const iso=isoLocal(d), p=jalaliParts(iso);
  if(p.year===year&&p.month===month)found.push({iso,day:p.day,date:new Date(d)});
 }
 return found;
};
const jalaliMonthName = (date) => new Intl.DateTimeFormat('fa-IR-u-ca-persian',{month:'long'}).format(date);

function JalaliDatePicker({value,onChange,label='تاریخ'}) {
 const [open,setOpen]=useState(false);
 const [month,setMonth]=useState(()=>jalaliParts(value));
 const p=jalaliParts(value);
 const fmt=n=>new Intl.NumberFormat('fa-IR',{useGrouping:false}).format(n);
 const days=jalaliMonthDays(month.year,month.month);
 const blanks=days.length?(days[0].date.getDay()+1)%7:0;
 return <div className="jalali-date-field"><label>{label}<input type="text" readOnly value={fmt(p.year)+'/'+fmt(p.month).padStart(2,'۰')+'/'+fmt(p.day).padStart(2,'۰')} onClick={()=>{setMonth(jalaliParts(value));setOpen(v=>!v);}} placeholder="انتخاب تاریخ شمسی"/></label>{open&&<div className="jalali-calendar" dir="rtl"><div className="jalali-calendar-head"><button type="button" className="btn btn-ghost" onClick={()=>setMonth(v=>v.month===1?{year:v.year-1,month:12}:{...v,month:v.month-1})}>‹</button><b>{jalaliMonthName(days[10]?.date||days[0]?.date||new Date())} {fmt(month.year)}</b><button type="button" className="btn btn-ghost" onClick={()=>setMonth(v=>v.month===12?{year:v.year+1,month:1}:{...v,month:v.month+1})}>›</button></div><div className="jalali-calendar-grid">{['ش','ی','د','س','چ','پ','ج'].map((w,i)=><span className="jalali-weekday" key={i}>{w}</span>)}{Array.from({length:blanks},(_,i)=><span key={'blank'+i}/>)}{days.map(d=><button type="button" key={d.iso} className={d.iso===value?'selected':''} onClick={()=>{onChange(d.iso);setOpen(false);}}>{fmt(d.day)}</button>)}</div><button type="button" className="btn btn-ghost jalali-today" onClick={()=>{const today=isoLocal(new Date());onChange(today);setMonth(jalaliParts(today));setOpen(false);}}>امروز</button></div>}</div>;
}

