 const sizedSaleProducts=matchingSaleProducts.filter(p=>sizeKey(p)===saleSize);
 const selectedSaleProduct=sizedSaleProducts.find(p=>String(p.id)===String(saleForm.productId))||sizedSaleProducts[0]||null;
 
 const addProduct=async e=>{e.preventDefault();try{if(!branch)throw new Error('شعبه هنوز بارگذاری نشده است.');const productName=[form.category,form.variant&&form.variant!=='ساده'?form.variant:'',form.color&&form.color!=='-'?form.color:''].filter(Boolean).join(' ');const productSku='SAL-'+Date.now().toString(36).toUpperCase();const p=await createProduct(branch.id,{...form,stock:numericValue(form.stock),buy:0,price:numericValue(form.price),name:productName,sku:productSku});setProducts([p,...products]);setShowProduct(false);setForm({name:'',sku:'',category:'کت شلوار',variant:'کت شلوار ساده',size:'50',color:'مشکی',stock:'1',price:''});toast('کالا در پایگاه داده ذخیره شد.');}catch(err){toast(err.message||'ذخیره کالا ناموفق بود.');}};
 const addSale=async e=>{e.preventDefault();if(!branch||!session){toast('ابتدا وارد حساب کاربری شوید.');return;}if(!selectedSaleProduct){toast('لطفاً کالای دارای موجودی را انتخاب کنید.');return;}const qty=Number(saleForm.qty);const discount=Number(saleForm.discount)||0;const isGift=saleForm.payment==='هدیه';if(!Number.isInteger(qty)||qty<1){toast('تعداد باید حداقل ۱ عدد باشد.');return;}if(qty>Number(selectedSaleProduct.stock||0)){toast('موجودی کافی نیست.');return;}if(isGift&&discount>0){toast('برای هدیه، تخفیف جداگانه وارد نکنید.');return;}if(discount<0||discount>(Number(selectedSaleProduct.price)||0)*qty){toast('مبلغ تخفیف معتبر نیست.');return;}try{setDataLoading(true);const soldAt=new Date(saleDate+'T12:00:00').toISOString();const {data,error}=await supabase.rpc('register_sale',{p_branch_id:branch.id,p_product_id:selectedSaleProduct.id,p_quantity:qty,p_gift_quantity:0,p_sold_at:soldAt,p_discount:isGift?0:discount,p_customer_name:saleForm.customer.trim()||null,p_payment_method:saleForm.payment});if(error)throw error;await loadRemote(session);const invoiceDate=new Date(soldAt);const invoiceTotal=isGift?0:Math.max(0,(Number(selectedSaleProduct.price)||0)*qty-discount);setInvoice({number:data?.invoice_no||('SAL-'+invoiceDate.getTime()),date:invoiceDate,customer:saleForm.customer.trim()||'مشتری حضوری',product:selectedSaleProduct.name||[selectedSaleProduct.category,productVariant(selectedSaleProduct),selectedSaleProduct.color].filter(Boolean).join(' '),sku:selectedSaleProduct.sku||'',size:selectedSaleProduct.size||'',color:selectedSaleProduct.color||'',qty,giftQuantity:isGift?qty:0,unitPrice:isGift?0:Number(selectedSaleProduct.price)||0,discount:isGift?0:discount,total:invoiceTotal,payment:saleForm.payment});setSaleForm({productId:'',category:'',variant:'',color:'',qty:1,customer:'',discount:0,payment:'کارت‌خوان'});toast('فروش ثبت شد؛ فاکتور آماده ارسال است.');}catch(err){toast(err.message||'ثبت فروش انجام نشد.');}finally{setDataLoading(false);}};
 const exchangeSale=sales.find(x=>String(x.id)===String(exchangeForm.saleId))||null;
 const exchangeSaleItem=exchangeSale?.items?.find(x=>String(x.id)===String(exchangeForm.saleItemId))||null;
 const exchangeNewProduct=products.find(x=>String(x.id)===String(exchangeForm.newProductId))||null;
 const exchangeReturnUnit=exchangeSaleItem&&exchangeSaleItem.quantity>0?Number((exchangeSaleItem.lineTotal/exchangeSaleItem.quantity).toFixed(2)):0;
 const exchangeReturnTotal=exchangeReturnUnit*Math.max(0,Number(exchangeForm.returnQuantity)||0);
 const exchangeNewTotal=(Number(exchangeNewProduct?.price)||0)*Math.max(0,Number(exchangeForm.newQuantity)||0);
 const exchangeDifference=exchangeNewTotal-exchangeReturnTotal;
 const submitExchange=async e=>{e.preventDefault();if(!branch||!session){toast('ابتدا وارد حساب کاربری شوید.');return;}if(!exchangeSale||!exchangeSaleItem||!exchangeNewProduct){toast('فاکتور، کالای برگشتی و کالای جایگزین را انتخاب کنید.');return;}if(Number(exchangeForm.returnQuantity)<1||Number(exchangeForm.returnQuantity)>(exchangeSaleItem.quantity-exchangeSaleItem.returnedQuantity)){toast('تعداد برگشتی از مقدار باقی‌مانده فاکتور بیشتر است.');return;}if(Number(exchangeForm.newQuantity)<1){toast('تعداد کالای جایگزین معتبر نیست.');return;}if(exchangeDifference>0&&!['cash','card','transfer'].includes(exchangeForm.settlementMethod)){toast('برای دریافت اختلاف، روش دریافت وجه را انتخاب کنید.');return;}if(exchangeDifference<0&&!['cash','card','transfer','credit'].includes(exchangeForm.settlementMethod)){toast('روش استرداد یا اعتبار مشتری را انتخاب کنید.');return;}try{setExchangeBusy(true);const result=await registerSaleExchange(branch.id,{saleId:exchangeSale.id,saleItemId:exchangeSaleItem.id,returnQuantity:exchangeForm.returnQuantity,newProductId:exchangeNewProduct.id,newQuantity:exchangeForm.newQuantity,returnCondition:exchangeForm.returnCondition,settlementMethod:exchangeDifference===0?'none':exchangeForm.settlementMethod,notes:exchangeForm.notes});await loadRemote(session);setExchangeForm({saleId:'',saleItemId:'',returnQuantity:1,newProductId:'',newQuantity:1,returnCondition:'resalable',settlementMethod:'cash',notes:''});toast('تعویض با موفقیت ثبت شد؛ اختلاف: '+money(Math.abs(Number(result?.difference)||0))+(Number(result?.difference)>0?' دریافت از مشتری':Number(result?.difference)<0?' قابل استرداد به مشتری':''));}catch(err){toast(err.message||'ثبت تعویض ناموفق بود.');}finally{setExchangeBusy(false);}};
 const addTransfer=async e=>{e.preventDefault();if(!branch||!session){toast('ابتدا وارد حساب کاربری شوید.');return;}const quantity=Number(transferForm.quantity);if(!Number.isInteger(quantity)||quantity<1){toast('تعداد انتقال باید حداقل ۱ عدد باشد.');return;}const product=products.find(p=>String(p.id)===String(transferForm.productId));if(!product){toast('کالای موردنظر را انتخاب کن.');return;}if(quantity>Number(product.stock||0)){toast('موجودی کافی نیست؛ موجودی فعلی: '+num(product.stock));return;}if(!['مکنزی','سالکو خرم آباد','سالکو دورود','سالکو بروجرد'].includes(transferForm.recipient)){toast('شعبه مقصد معتبر نیست.');return;}try{setTransferBusy(true);const transferredAt=new Date(transferForm.date+'T12:00:00').toISOString();const {data,error}=await supabase.rpc('register_inventory_transfer',{p_branch_id:branch.id,p_product_id:product.id,p_quantity:quantity,p_recipient_branch:transferForm.recipient,p_transferred_at:transferredAt,p_note:transferForm.note.trim()||null});if(error)throw error;await loadRemote(session);const {data:rows,error:rowsError}=await supabase.from('inventory_transfers').select('id,product_id,recipient_branch,quantity,transferred_at,note').eq('branch_id',branch.id).order('transferred_at',{ascending:false}).limit(50);if(rowsError)throw rowsError;setTransfers(rows||[]);setTransferForm({...transferForm,quantity:1,note:''});toast('انتقال کالا ثبت شد و از موجودی شعبه مبدأ کسر شد.');}catch(err){toast(err.message||'ثبت انتقال کالا ناموفق بود.');}finally{setTransferBusy(false);}};
 const addCash=async e=>{e.preventDefault();try{if(!branch)throw new Error('شعبه هنوز بارگذاری نشده است.');const item=await createCashTransaction(branch.id,branch.userId,{...cashForm,amount:Number(cashForm.amount)});setCash([item,...cash]);setShowCash(false);toast('تراکنش صندوق در پایگاه داده ذخیره شد.');}catch(err){toast(err.message||'ثبت تراکنش ناموفق بود.');}};
 const saveSaleAmount=async e=>{e.preventDefault();if(!editingSale||saleBusy)return;const amount=numericValue(editingSale.total);if(amount<0){toast('مبلغ فروش نمی‌تواند منفی باشد.');return;}setSaleBusy(true);try{const {error}=await supabase.from('sales').update({total:amount}).eq('id',editingSale.id).eq('branch_id',branch.id).eq('status','completed');if(error)throw error;setSales(prev=>prev.map(s=>s.id===editingSale.id?{...s,total:amount}:s));setEditingSale(null);toast('مبلغ فروش اصلاح و گزارش‌ها به‌روزرسانی شد.');}catch(err){toast(err.message||'اصلاح مبلغ فروش ناموفق بود.');}finally{setSaleBusy(false);}};
 const cancelSale=async sale=>{if(!branch||saleBusy)return;if(!window.confirm('فروش فاکتور '+(sale.invoiceNo||sale.id)+' لغو شود؟ موجودی کالا نیز به انبار برمی‌گردد.'))return;setSaleBusy(true);try{for(const item of (sale.items||[])){if(!item.productId)throw new Error('شناسه کالای فاکتور پیدا نشد؛ برای جلوگیری از مغایرت، فروش لغو نشد.');const {data:product,error:readError}=await supabase.from('products').select('stock_qty').eq('id',item.productId).eq('branch_id',branch.id).single();if(readError)throw readError;const {error:stockError}=await supabase.from('products').update({stock_qty:Number(product.stock_qty||0)+Number(item.quantity||0)}).eq('id',item.productId).eq('branch_id',branch.id);if(stockError)throw stockError;}const {error}=await supabase.from('sales').update({status:'cancelled'}).eq('id',sale.id).eq('branch_id',branch.id).eq('status','completed');if(error)throw error;const {error:cashError}=await supabase.from('cash_transactions').delete().eq('sale_id',sale.id).eq('branch_id',branch.id);if(cashError)throw cashError;setSales(prev=>prev.filter(s=>s.id!==sale.id));setProducts(prev=>prev.map(p=>{const restored=(sale.items||[]).filter(i=>String(i.productId)===String(p.id)).reduce((n,i)=>n+Number(i.quantity||0),0);return restored?{...p,stock:p.stock+restored}:p;}));await loadRemote(session);toast('فروش لغو شد؛ موجودی کالا و دریافت مرتبط با فاکتور از صندوق اصلاح شد.');}catch(err){toast('لغو فروش کامل نشد: '+(err.message||'خطای پایگاه داده')+'؛ موجودی و وضعیت فاکتور را بررسی کن.');await loadRemote(session);}finally{setSaleBusy(false);}};
 const cashBalance=cash.reduce((s,x)=>s+(x.type==='دریافت'?x.amount:-x.amount),0);
 const exportCsv=()=>{const rows=[['نام کالا','کد','دسته','سایز','رنگ','موجودی','قیمت فروش'],...products.map(p=>[p.name,p.sku,p.category,p.size,p.color,p.stock,p.price])];const csv='\ufeff'+rows.map(r=>r.map(v=>'"'+String(v??'').replaceAll('"','""')+'"').join(',')).join('\n');const a=document.createElement('a');a.href=URL.createObjectURL(new Blob([csv],{type:'text/csv;charset=utf-8;'}));a.download='salco-inventory.csv';a.click();URL.revokeObjectURL(a.href);};
