 const exportDailyReportImage=async()=>{let staging=null,canvas=null;try{const report=document.querySelector(".daily-report-print");if(!report){toast("گزارش برای خروجی تصویر پیدا نشد.");return;}toast("در حال ساخت تصویر گزارش…");staging=document.createElement("div");staging.style.cssText="position:fixed;left:-12000px;top:0;width:720px;max-width:720px;overflow:visible;background:#080808;z-index:-1;";const clone=report.cloneNode(true);clone.id="salco-png-export";clone.classList.add("daily-report-pdf","daily-report-png");clone.querySelector(".salco-report-summary")?.remove();clone.style.cssText="display:block;width:720px;max-width:720px;min-width:0;height:auto;min-height:0;max-height:none;margin:0;padding:0;box-sizing:border-box;overflow:hidden;border:0;border-radius:0;background:#080808;";const exportStyle=document.createElement("style");exportStyle.textContent="#salco-png-export,#salco-png-export *{color:#fff!important;text-shadow:none!important;box-sizing:border-box!important;max-width:100%!important}.daily-report-png .salco-report-details{margin-top:18px!important}.daily-report-png .salco-report-details h3{font-size:24px!important;line-height:1.7!important;color:#fff!important}.daily-report-png .salco-signature-table th{font-size:20px!important;line-height:1.8!important;padding:17px 12px!important;color:#fff!important}.daily-report-png .salco-signature-table td{font-size:20px!important;line-height:1.9!important;font-weight:700!important;padding:20px 12px!important;color:#fff!important}.daily-report-png .salco-signature-table tfoot th{font-size:20px!important;padding:18px 12px!important;color:#fff!important}.daily-report-png .salco-report-title h2{font-size:30px!important;color:#fff!important}.daily-report-png .salco-report-title p,.daily-report-png .salco-report-date small{font-size:18px!important;color:#fff!important}.daily-report-png .salco-report-date b{font-size:22px!important;color:#fff!important}.daily-report-png .salco-report-kicker{color:#fff!important}.daily-report-png .salco-footer-copy b{font-size:20px!important;color:#fff!important}.daily-report-png .salco-footer-copy small,.daily-report-png .salco-footer-copy p,.daily-report-png .salco-footer-copy em{font-size:16px!important;line-height:1.9!important;color:#fff!important}.daily-report-png .salco-footer-brand strong,.daily-report-png .salco-footer-brand span{color:#fff!important}.daily-report-png .salco-report-details,.daily-report-png .salco-signature-table{break-inside:avoid!important;page-break-inside:avoid!important}";clone.prepend(exportStyle);staging.appendChild(clone);document.body.appendChild(staging);const logo=clone.querySelector(".salco-report-logo img");if(logo){logo.src=`${import.meta.env.BASE_URL}images/salco-logo.webp`;if(!logo.complete||!logo.naturalWidth)await new Promise(resolve=>{logo.onload=resolve;logo.onerror=resolve;});}const canvas=await html2canvas(clone,{scale:1,width:720,windowWidth:720,useCORS:true,backgroundColor:"#080808",scrollX:0,scrollY:0,logging:false,imageTimeout:300,removeContainer:true});const dataUrl=canvas.toDataURL("image/png");const filename=`SALCO-گزارش-روزانه-${reportDate}.png`;if(Capacitor.isNativePlatform()){const base64=dataUrl.split(",")[1];if(!base64)throw new Error("ساخت تصویر ناموفق بود");await Filesystem.writeFile({path:filename,data:base64,directory:Directory.Documents,recursive:true});toast("تصویر PNG ذخیره شد: Documents / "+filename);}else{const a=document.createElement("a");a.href=dataUrl;a.download=filename;document.body.appendChild(a);a.click();a.remove();toast("تصویر PNG گزارش دانلود شد.");}}catch(err){console.error("Daily report image export failed",err);toast("ساخت تصویر ناموفق بود: "+(err?.message||"دوباره تلاش کن."));}finally{if(canvas){canvas.width=0;canvas.height=0;}if(staging?.parentNode)staging.parentNode.removeChild(staging);}};
